function findRoot(parent: Map<string, string>, id: string): string {
  const lineage: string[] = [];
  let root = id;
  while (parent.get(root) !== root) {
    lineage.push(root);
    root = parent.get(root) ?? root;
  }
  for (const member of lineage) parent.set(member, root);
  return root;
}

